    ids,
    energyIds: pick(ENERGY_KEYS),
    // today / current month: without the two check-only counters (fewer queries)
    periodIds: pick(ENERGY_KEYS.filter((k) => !CHECK_ONLY_KEYS.includes(k))),
    tempIds: pick(TEMP_KEYS),
