// Number locale and month names; set per render from hass.locale (module-level so the
// SVG helpers below can use them too).
let LOC = "en";
let MONTHS = [];
const nf = (v, d = 0) => fmt(v, d, LOC);
const tpl = (s, vars) => s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? "");

const pad = (n) => String(n).padStart(2, "0");
const withTimeout = (p, ms, msg) =>
  Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error(msg)), ms))]);

// Time zone helpers: statistic buckets are aligned to the HA time zone, not the browser's.
function zParts(ts, tz) {
  const p = Object.fromEntries(new Intl.DateTimeFormat("en-CA", {
    timeZone: tz, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit", hourCycle: "h23",
  }).formatToParts(ts).map((x) => [x.type, x.value]));
  return { y: +p.year, m: +p.month - 1, d: +p.day, h: +p.hour, mi: +p.minute, s: +p.second };
}
/** Date of 00:00 on y-m-d in time zone tz. */
function zStart(y, m, d, tz) {
  let ts = Date.UTC(y, m, d);
  for (let i = 0; i < 2; i++) {
    const p = zParts(ts, tz);
    ts -= Date.UTC(p.y, p.m, p.d, p.h, p.mi, p.s) - Date.UTC(y, m, d);
  }
  return new Date(ts);
}
/** Closed months (YYYY-MM) from the start month on; the previous month only CACHE_GRACE_H hours after it ended. */
function closedMonths(y0, m0, n, now, tz) {
  const out = [];
  for (let y = y0, m = m0; y < n.y || (y === n.y && m < n.m); m === 11 ? (y++, (m = 0)) : m++) {
    const end = m === 11 ? zStart(y + 1, 0, 1, tz) : zStart(y, m + 1, 1, tz);
    if (now - end >= CACHE_GRACE_H * 3600e3) out.push(`${y}-${pad(m + 1)}`);
  }
  return out;
}
const nextKey = (k) => { const [y, m] = k.split("-").map(Number); return m === 12 ? `${y + 1}-01` : `${y}-${pad(m + 1)}`; };
const monthKeyTz = (ms, tz) => { const p = zParts(ms, tz); return `${p.y}-${pad(p.m + 1)}`; };
